@functools.lru_cache(None)
def get_result(state):
    s = sum(state)
    m = max(state)
    if m > s - m or all(x == 0 for x in state):
        return len(state)

    best_for_a = -1
    n = len(state)
    for i in range(n):
        for j in range(i + 1, n):
            x, y = state[i], state[j]
            base_state = list(state)
            base_state.pop(j)
            base_state.pop(i)

            z1 = x + y
            z2 = abs(x - y)

            res1 = get_result(tuple(sorted(base_state + [z1])))
            res2 = get_result(tuple(sorted(base_state + [z2])))

            result_for_this_pair = min(res1, res2)

            if result_for_this_pair > best_for_a:
                best_for_a = result_for_this_pair

    return best_for_a

