def solve():
    memo = {}

    def get_cookies(state):
        state = tuple(sorted(state))
        if state in memo:
            return memo[state]

        # Check termination conditions
        if not state:
            return 0

        max_val = max(state)
        sum_others = sum(state) - max_val
        if max_val > sum_others:
            return len(state)

        if all(x == 0 for x in state):
            return len(state)

        # Player A's turn to pick x, y
        best_cookies = 0

        # A picks x, y
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                x, y = state[i], state[j]

                # B's turn to choose x+y or |x-y|
                res1 = get_cookies(list(state[:i] + state[i+1:j] + state[j+1:]) + [x+y])
                res2 = get_cookies(list(state[:i] + state[i+1:j] + state[j+1:]) + [abs(x-y)])

                # B chooses the minimum of the two
                cookies_for_this_pair = min(res1, res2)

                # A chooses the pair that maximizes this minimum
                if cookies_for_this_pair > best_cookies:
                    best_cookies = cookies_for_this_pair

        memo[state] = best_cookies
        return best_cookies

    for n in range(1, 11):
        memo = {}
        initial_state = [1] * n
        print(f"N={n}: {get_cookies(initial_state)}")

